INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62793039', 62793039, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Pemutakhiran Masterplan Jalur Kereta Api Pulau Sumatera', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 2000000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Meninjau kembali arah kebijakan serta rencana pengembangan jalur KA Pulau Sumatera baik untuk angkutan barang dan penumpang sebagaimana dalam dokumen masterplan terdahulu yang selanjutnya akan disesuaikan dengan perkembangan wilayah, serta menjaring aspirasi Pemerintah Daerah setempat dan swasta.', '1. Melakukan evaluasi terhadap arah dan rencana pembangunan perkeretaapian Pulau Sumatera yang tertuang dalam Masterplan terdahulu; 2. Melakukan survei reconnaissance dan inventarisasi data sekunder studi kajian Masterplan Pulau Sumatera guna memperoleh data-data yang diperlukan di wilayah studi; 3. Mengidentifikasi peraturan perundang-undangan dan pemerintah yang terkait dengan studi Masterplan Pulau Sumatera; 4. Melakukan reviu terhadap dokumen-dokumen perencanaan terkait; 5. Mengidentifikasi dan melakukan review terhadap dokumen perencanaan Pemerintah Pusat/Pemerintah Provinsi/Pemerintah Kabupaten dan Kota (RPJP/RPJMN/RTRW/RIPP) terkait rencana pengembangan perkeretaapian; 6. Melakukan evaluasi kondisi perkeretaapian terkini termasuk identifikasi potensi dan permasalahan di Pulau Sumatera; 7. Menganalisis proyeksi/prediksi kebutuhan prasarana, sarana dan operasi/pelayanan kereta api dalam kurun waktu 20 (dua puluh) tahun ke depan; 8. Melakukan survei primer data koridor, tata guna lahan, dan fasilitas pendukung perkeretaapian di wilayah kajian; 9. Melakukan Identifikasi pola pergerakan orang dan barang inter dan intra zona serta proyeksi kebutuhan perjalanan perkeretaapian dalam kurun waktu minimal 20 tahun; 10. Melakukan kajian kelayakan terhadap rute jalur kereta api baik secara teknis, finansial dan ekonomi; 11. Menyusun tahapan prioritas pembangunan, skema pembiayaan dan kajian manajemen risiko; 12. Melakukan analisa potensi pembiayaan pembangunan dengan skema alternatif selain APBN; 13. Menyusun dan merumuskan arah kebijakan serta langkah-langkah strategis Pemerintah Pusat maupun Daerah dalam rangka pengembangan jaringan KA di Pulau Sumatera; 14. Menyusun draft Peraturan Menteri Perhubungan tentang Masterplan Jalur KA Pulau Sumatera.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 72029);
