INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62793515', 62793515, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Studi penyusunan Rancangan Peraturan Menteri Tentang Tata Cara Penyusunan Rencana Induk Perkeretaapian dan Rencana Pembangunan Perkeretaapian', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1050000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Melakukan penelitian dan pengkajian hukum tentang tata cara penyusunan rencana induk perkeretaapian dan rencana pembangunan perkeretaapian yang dapat dipertanggungjawabkan secara ilmiah mengenai pengaturan masalah tersebut dalam rancangan peraturan Menteri.', 'a. Dasar Filosofis, memuat cita hukum sesuai Pancasila dan Konstitusi UUD NRI 1945 yang bertujuan agar peraturan mempunyai visi dan dapat berlaku waktu yang Panjang; b. Dasar Sosiologis, memuat kondisi praktik di masyarakat yang ada (tujuannya agar peraturan dapat berlakuk efektif karena diterima masyarakat secara wajar; c. Dasar yuridis, peraturan memiliki kaidah yang sah secara hukum, mempertimbangkan alasan hukum dan menjamin kepastian hukum; d. Mengidentifikasi peraturan perundang-undangan dan pemerintah yang terkait dengan Naskah Akademik Tentang Tata Cara Penyusunan Rencana Induk Perkeretaapian dan Rencana Pembangunan Perkeretaapian; e. Melakukan review terhadap indikator/parameter yang digunakan dalam penetapan tahapan pembangunan pada dokumen-dokumen perencanaan awal seperti kajian kelayakan maupun basic design; f. Mengidentifikasi rencana, prioritas dan tahapan kebutuhan pengembangan jaringan perkeretaapian; g. Mengidentifikasi aspek-aspek penyusunan Rencana Induk Perkeretaapian meliputi kajian survei investigasi dasar (SID) / aspek transportasi, ekonomi, finansial, kewilayahan, sosial budaya dan lingkungan; h. Melakukan kajian secara terukur dan teknis terhadap rumusan indikator; i. Merumuskan kebijakan berdasarkan Peraturan dan hasil analisa yang telah dilakukan; j. Menyusun rancangan Peraturan Menteri sesuai dengan kaidah hukum.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 72364);
