INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62793858', 62793858, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Kajian Evaluasi Capaian dan Reviu Terhadap Rencana Induk Perkeretaapian Nasional (RIPNas)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1500000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Melakukan penelitian dan pengkajian evaluasi capaian dan reviu terhadap Rencana Induk Perkeretaapian Nasional (Ripnas) untuk memberikan arahan tentang pengembangan perkeretaapian nasional sampai tahun 2030. yang dapat dipertanggungjawabkan secara ilmiah mengenai pengaturan masalah tersebut dalam rancangan peraturan Menteri.', 'a. Mengidentifikasi dan melalukan invetarisasi peraturan perundang-undangan termasuk SOP yang terkait dengan Penyusunan Rencana Induk Perkeretaapian Nasional; b. Melakukan evaluasi kondisi perkeretaapian terkini termasuk identifikasi potensi dan permasalahan Rencana Induk Perkeretaapian Nasional; c. Melakukan analisa untuk merumuskan arah pengembangan dan kebijakan Pereketaapian Nasional; d. Mengidentifikasi dan melakukan review terhadap dokumen perencanaan Pemerintah Pusat/Pemerintah Provinsi/Pemerintah Kabupaten dan Kota (RPJP/RPJMN/RTRW/RIPP) terkait rencana pengembangan perkeretaapian; e. Melakukan Gap Analysis terhadap capaian RIPNAS sampai dengan tahun 2024; f. Melakukan kajian kelembagaan dengan kondisi lingkungan strategis; g. Melakukan evaluasi kebutuhan sarana dan prasarana serta mengidentifikasi teknologi Perkeretaapian terbarukan sampai dengan tahun 2030; h. Melakukan evaluasi dan analisa kebutuhan pada aspek regulasi, kelembagaan dan SDM Perkeretaapian sampai dengan tahun 2030; i. Melakukan analisa untuk merumuskan strategi dan tahapan sesuai dengan readiness criteria dengan menentukan skala prioritas kebutuhan pengembangan serta pembangunan jaringan perkeretaapian seluruh Indonesia; j. Melakukan benchmarking Rencana Induk Perkeretaapian di Negara lain; k. Menyusun lampiran rancangan Peraturan Menteri atau Keputusan Menteri sesuai dengan kaidah hukum.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 73515);
