INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62794247', 62794247, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Kajian Evaluasi dan Dampak Terhadap Capaian Proyek Strategis Nasional (PSN) BidangPerekeretaapian', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1900000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Melakukan evaluasi manfaat terhadap hasil Pembangunan PSN bidang perkeretaapian yang telah dilaksanakan oleh Direktorat Jenderal Perkeretaapian termasuk mengkaji potensi PSN bidang perkeretaapian diantaranya meliputi aspek transportasi, ekonomi, finansial, kewilayahan, sosial budaya dan lingkungan serta identifikasi potensi dan permasalahan dalam pemanfaatan hasil pembangunan tersebut', '1. Melakukan survei reconnaissance dan inventarisasi data sekunder studi kajian manfaat terkait PSN bidang perkeretaapian guna memperoleh data-data yang diperlukan di wilayah studi; 2. Mengidentifikasi peraturan perundang-undangan dan pemerintah yang terkait dengan studi kajian manfaat terkait PSN bidang perkeretaapian; 3. Melakukan reviu terhadap dokumen-dokumen perencanaan terkait; 4. Melakukan kajian potensi daerah terhadap RTRW dan Tatrawil/Tatralok wilayah PSN bidang perkeretaapian; 5. Mengidentifikasi indikator-indikator evaluasi manfaat diantaranya aspek transportasi, ekonomi, finansial, kewilayahan, sosial budaya dan lingkungan; 6. Mengidentifikasi kondisi prasarana, sarana dan operasi/pelayanan transportasi PSN bidang perkeretaapian; 7. Melakukan kajian evaluasi manfaat/dampak secara terukur dan teknis untuk pengoperasian PSN bidang perkeretaapian baik bagi pengguna KA, masyarakat sekitar, Pemerintah dan Stakeholder lainnya baik di level lokal, regional dan nasional; 8. Melakukan kajian potensi dan permasalahan terhadap hasil evaluasi manfaat/dampak pengoperasian PSN bidang perkeretaapian; 9. Menganalisis proyeksi/prediksi kebutuhan prasarana, sarana dan operasi/pelayaan PSN bidang perkeretaapian dalam kurun waktu 5 (lima) tahun ke depan; 10. Menyusun rekomendasi kebijakan, strategi serta rencana aksi untuk penyempurnaan program pembangunan dalam upaya optimalisasi hasil pembangunan serta peningkatan pelayanan PSN bidang perkeretaapian; 11. Melakukan survei primer data koridor, tata guna lahan dan fasilitas pendukung perkeretaapian di wilayah alternatif; 12. Melakukan survei primer lalu lintas (traffic count, travel time, roadside interview) dan stated preference di wilayah alternatif untuk potensi perpanjangan layanan PSN bidang perkeretaapian; 13. Melakukan analisa pola pergerakan orang dan barang inter dan intra zona serta proyeksi kebutuhan perjalanan perkeretaapian dalam kurun waktu minimal 20 tahun PSN bidang perkeretaapian; 14. Melakukan kajian kelayakan terhadap rute jalur kereta api baik secara teknis, finansial dan ekonomi; 15. Menyusun tahapan pembangunan, skema pembiayaan dan kajian manajemen risiko; 16. Lokasi pekerjaan di Jakarta, dengan ruang lingkup pelaksanaan survei di wilayah Jabodetabek, Jawa Barat(Bandung) dan Makasar serta wilayah lain yang menjadi bangkitan atau tarikan penumpang KA.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 75141);
