INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64016231', 64016231, 'analyze_legacy', 'Provinsi Sulawesi Selatan', 'provinsi', 'UPT TRANSFUSI DARAH', 'Belanja Pemeliharaan Alat Angkutan-Alat Angkutan Darat Bermotor Lainnya', 'Barang', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 150000000, 'January 2026', 'BLUD', 1, 1, '1 Tahun', 'Belanja Pemeliharaan Alat Angkutan Darat Bermotor Lainnya merupakan kegiatan pemeliharaan kendaraan operasional selain kendaraan dinas roda dua dan roda empat utama, yang digunakan untuk mendukung kelancaran pelaksanaan tugas dan fungsi unit kerja.', 'Jenis Pemeliharaan Servis berkala (tune up ringan/sedang). Perbaikan kerusakan minor hingga sedang. Penggantian oli, filter, dan cairan pendukung kendaraan. Perawatan sistem rem, kelistrikan, dan mesin.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 75595);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62814732', 62814732, 'analyze_legacy', 'Provinsi Gorontalo', 'provinsi', 'Sekretariat DPRD', 'Belanja Sewa Peralatan Studio Audio dapil 3 masa persidangan 3', 'Barang', 'Pengadaan Langsung', 'Gorontalo, Gorontalo (Kota)', 130000000, 'May 2026', 'APBD', 1, 1, '1 kegiatan', 'Belanja Sewa Peralatan Studio Audio dapil 3 masa persidangan 3', 'Belanja Sewa Peralatan Studio Audio dapil 3 masa persidangan 3', 130000000, 'absurd', 'Pengadaan sewa peralatan studio audio untuk kegiatan persidangan DPRD berindikasi tidak selaras dengan kebutuhan dasar fungsi legislatif dan berpotensi menjadi belanja penunjang yang berlebihan. Nilai anggaran penuh patut dicermati sebagai potensi pemborosan karena objek sewanya terkesan tidak esensial bagi layanan publik inti.', NULL, NULL, 4, 1, 1, 1, 1, 75596);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64001329', 64001329, 'analyze_legacy', 'Provinsi Sulawesi Selatan', 'provinsi', 'UPT TRANSFUSI DARAH', 'Belanja Obat-Obatan-Obat-Obatan Lainnya ( Tabung Vacum Ungu )', 'Barang', 'E-Purchasing', 'Sulawesi Selatan, Makassar (Kota)', 300000, 'January 2026', 'BLUD', 1, 0, '2 Pack', 'Tabung vacuum ungu adalah tabung pengumpul darah medis sekali pakai yang dilengkapi dengan antikoagulan EDTA (Ethylenediaminetetraacetic Acid). Tabung ini digunakan untuk mencegah pembekuan darah, sehingga sangat penting untuk pemeriksaan darah lengkap (Complete Blood Count/CBC), analisis komponen darah, tipe darah, serta beberapa tes hematologi lainnya. EDTA bekerja dengan mengikat ion kalsium sehingga proses pembekuan darah tidak terjadi pada sampel yang dikumpulkan', 'Bahan Tabung: PET (Polyethylene Terephthalate) atau Gelas medis yang transparan, kuat, dan steril. Penutup (Cap): Plastik dengan kode warna ungu/lavender sesuai standar identifikasi tabung darah. Antikoagulan / Additive EDTA-K2 atau EDTA-K3: Antikoagulan yang dilapisi di dinding tabung untuk menjaga darah tetap tidak menggumpal selama pengambilan dan penyimpanan awal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 75597);
